 @Test void disableStopsNewDispatchWithoutCancellingQueuedItem()throws Exception{enable();var h=enqueue(1,5);disable();dispatch.poll();assertEquals("QUEUED",queue.lookup(h.requestId()).state());assertEquals(0,rows("irrigation_session"));}
 @Test void disableDoesNotPauseOrOffAlreadyArmedCycle()throws Exception{enable();enqueue(1,5);dispatch.poll();var l=link();disable();assertEquals("ARMED",state(l.sessionId()).state());cycle.poll();assertEquals("WAIT_OPEN",state(l.sessionId()).state());assertEquals(0,count("pump_command","OFF"));}
 @Test void startupDisablesAndOldEnableDuplicateCannotReauthorize()throws Exception{var d=enableRequest();dispatch.save(d);enqueue(1,5);dispatch.interruptOnStartup();assertFalse(dispatch.save(d).enabled());dispatch.poll();assertEquals(0,rows("irrigation_session"));enable();dispatch.poll();assertEquals("EXISTING_HEAD_REQUIRES_REVIEW",dispatch.snapshot().policy().result());}
 @Test void gapAndBackwardClockDisableWithoutCatchup()throws Exception{enable();enqueue(1,5);jdbc.update("UPDATE irrigation_queue_dispatch_state SET last_tick_at=CURRENT_TIMESTAMP-INTERVAL '31 seconds'");dispatch.poll();assertFalse(dispatch.snapshot().policy().enabled());assertEquals("CLOCK_OR_WORKER_GAP",dispatch.snapshot().policy().result());enable();jdbc.update("UPDATE irrigation_queue_dispatch_state SET last_tick_at=CURRENT_TIMESTAMP+INTERVAL '3 seconds'");dispatch.poll();assertFalse(dispatch.snapshot().policy().enabled());assertEquals(0,rows("irrigation_session"));}
