 @Test void activeCycleBlocksSecondRequest()throws Exception{enable();enqueue(1,5);dispatch.poll();var second=enqueue(1,5);dispatch.poll();assertEquals(1,rows("irrigation_queue_dispatch_link"));assertEquals("QUEUED",queue.lookup(second.requestId()).state());assertEquals("SESSION_ACTIVE",dispatch.snapshot().policy().result());}
 @Test void failedCycleDisablesPolicyAndNeverStartsNext()throws Exception{enable();enqueue(1,5);dispatch.poll();enqueue(1,5);var l=link();cycle.pause("PR1",l.sessionId(),l.armId());dispatch.poll();assertEquals("CYCLE_INTERRUPTED",dispatch.snapshot().policy().result());assertFalse(dispatch.snapshot().policy().enabled());assertEquals(1,rows("irrigation_queue_dispatch_link"));}
 @Test void successfulSafeClosureWithEarlyStopDoesNotAuthorizeNext()throws Exception{enable();enqueue(1,5);dispatch.poll();var l=link();jdbc.update("UPDATE irrigation_session SET phase='CLOSED_CONFIRMED',finished_at=CURRENT_TIMESTAMP WHERE session_id=?",l.sessionId());jdbc.update("UPDATE irrigation_session_cycle SET state='COMPLETE',finished_at=CURRENT_TIMESTAMP,stop_at=CURRENT_TIMESTAMP,stop_reason='RUNNING_PROOF_LOST' WHERE session_id=?",l.sessionId());dispatch.poll();assertEquals("CYCLE_STOPPED_EARLY",dispatch.snapshot().policy().result());}
 @Test void completedCycleAllowsOnlyNextEligibleHead()throws Exception{enable();enqueue(1,5);dispatch.poll();var l=link();cycle.poll();opened(current(l.sessionId()));cycle.poll();onConfirmed(current(l.sessionId()));cycle.poll();timer(l.sessionId());cycle.poll();offConfirmed(current(l.sessionId()));cycle.poll();closed(current(l.sessionId()));cycle.poll();assertEquals("COMPLETE",state(l.sessionId()).state());var next=enqueue(1,5);dispatch.poll();assertEquals(1,rows("irrigation_queue_dispatch_link"));jdbc.update("UPDATE circuit_demo_gate SET close_fence_at=CURRENT_TIMESTAMP-INTERVAL '1 second' WHERE valve_id='VALVE78'");dispatch.poll();assertEquals(2,rows("irrigation_queue_dispatch_link"),dispatch.snapshot().toString());assertEquals("HANDED_OFF",queue.lookup(next.requestId()).state());assertEquals(1,count("pump_command","ON"));}
