 @Test void unconditionalStopIsIdempotentAndCannotCancelActiveCycle()throws Exception{enable();enqueue(1,5);dispatch.poll();var l=link();var stop=UUID.randomUUID();var p=dispatch.stop(stop);assertFalse(p.enabled());assertEquals("OPERATOR_STOPPED",p.result());assertEquals(p,dispatch.stop(stop));assertEquals("ARMED",state(l.sessionId()).state());mvc.perform(post("/api/v1/irrigation-queue/dispatch/stop").contentType("application/json").content(mapper.writeValueAsBytes(Map.of("stopId",stop)))).andExpect(status().isOk()).andExpect(jsonPath("enabled").value(false));}
 @Test void stopWhileDisabledSupersedesAlreadyReviewedEnableAndDuplicateDoesNotStopLaterEnable()throws Exception{var d=enableRequest();var id=UUID.randomUUID();dispatch.stop(id);assertThrows(Exception.class,()->dispatch.save(d));enable();assertTrue(dispatch.stop(id).enabled());}
 @Test void missingRouteRequiredProfileCannotAdvertiseOrEnableAuthority()throws Exception{var d=enableRequest();org.springframework.test.util.ReflectionTestUtils.setField(fencing,"routeRequired",false);try{assertFalse(dispatch.snapshot().canEnable());assertThrows(Exception.class,()->dispatch.save(d));}finally{org.springframework.test.util.ReflectionTestUtils.setField(fencing,"routeRequired",true);}}
